{
  "findings": [
    {
      "check_id": "CKV_AZURE_70",
      "title": "Ensure that Function apps is only accessible over HTTPS",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The azurerm_function_app resource does not explicitly enable HTTPS only, potentially allowing unencrypted HTTP traffic."
    },
    {
      "check_id": "CKV_AZURE_221",
      "title": "Ensure that Azure Function App public network access is disabled",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The azurerm_function_app resource does not disable public network access, potentially exposing the Function App to unauthorized access."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Ensure that function apps enables Authentication",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The azurerm_function_app resource does not enable authentication, potentially allowing unauthenticated access to the Function App."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n  https_only                 = true\n  auth_settings {\n    enabled = true\n  }\n}",
  "fix_summary": "Enabled HTTPS only, disabled public network access is not directly supported in azurerm_function_app, and enabled authentication for the Azure Function App."
}
